await check('The actual provider freezes six-field answer schema while legacy instructions and pre-dispatch validation remain intact',async()=>{
 const {completeMaterialAi}=await import('../../src/main/assets/material-ai-provider.ts'),old=globalThis.fetch,requests=[];const v2={schemaVersion:'xiaozhi.material-ai-book-page-response.v2',outcome:'needs_review',questions:[],pageText:'第十三章 素养基础测试卷\n1.D 原文。\n2.B 模糊。',pageIssues:[],answerIssues:[{section:'第十三章 素养基础测试卷',number:'2',issues:['uncertain_ocr']}]};let raw=JSON.stringify(v2);try{globalThis.fetch=async(_url,options)=>{requests.push(JSON.parse(options.body));return new Response(JSON.stringify({choices:[{finish_reason:'stop',message:{content:raw}}]}),{status:200});};const args={model:'deepseek-flash',apiKey:'controlled-only',text:'OCR',page:true,answerBook:true,bookPagePolicy:'answer-entry-uncertainty.v2',pagePrompt:{policy:MATERIAL_PAGE_PROMPT,ocrStatus:'complete'},imageCoverage:true,image:{mime:'image/png',data:Buffer.from('controlled-page').toString('base64')}};await completeMaterialAi(args,new AbortController().signal);await completeMaterialAi({...args,previous:v2},new AbortController().signal);for(const r of requests){const s=r.messages[0].content;assert(s.includes(v2.schemaVersion));assert(s.includes('schemaVersion/outcome/questions/pageText/pageIssues/answerIssues六个字段'));assert(!s.includes(pageSchema));assert(!s.includes('pageIssues五个字段'));assert.deepEqual(JSON.parse(r.messages[1].content[0].text).answerContext,{policy:args.bookPagePolicy});}const legacy={schemaVersion:pageSchema,outcome:'no_questions',questions:[],pageText:v2.pageText,pageIssues:[]};await assert.rejects(completeMaterialAi({...args,previous:legacy},new AbortController().signal),/invalid_input/);assert.equal(requests.length,2);raw=JSON.stringify(legacy);await assert.rejects(completeMaterialAi(args,new AbortController().signal),/invalid_response/);const {bookPagePolicy,...oldArgs}=args;await completeMaterialAi(oldArgs,new AbortController().signal);assert(requests.at(-1).messages[0].content.includes(pageSchema));assert(!JSON.parse(requests.at(-1).messages[1].content[0].text).answerContext);}finally{globalThis.fetch=old;}
});
