await check('Local OCR recovery preserves the sealed correction proof and all three paid receipts',async()=>{
 const f=await correctionFixture('ocr_error');try{await f.create();await f.repo.drain();await f.repo.drain();const raw=f.db.prepare('SELECT first_json,final_json FROM material_ai_units').get(),proof=f.db.prepare('SELECT * FROM material_ai_page_verifications').get(),id=(await f.question()).id;const columns={stem:'stem',answer:'answer',analysis:'analysis',subject:'subject',grade:'grade',knowledgePoint:'knowledge_point',questionType:'question_type',difficulty:'difficulty'};for(const column of Object.values(columns))f.db.exec('ALTER TABLE question_bank_items ADD COLUMN '+column+" TEXT NOT NULL DEFAULT ''");for(const q of f.saved)for(const [key,column]of Object.entries(columns))f.db.prepare('UPDATE question_bank_items SET '+column+'=? WHERE id=?').run(q[key],q.id);f.repo.runtime.inspectCrop=async()=>({schemaVersion:'xiaozhi.material-ai-crop-quality.v1',engine:'rapidocr-3.9.2-ort-1.30.0-ppocrv6-small.v1',text:'如图所示物体移动，计算七加八的结果。\n图1',clearEdges:[true,true,true,true]});await f.repo.action({schemaVersion:'xiaozhi.material-ai.v1',batchId:f.batch,action:'recheck_local'});await f.repo.drain();assert.equal(f.db.prepare('SELECT status FROM material_ai_crop_rechecks').get().status,'complete');const saved=await f.question();assert.equal(saved.id,id);assert(archiveEligible(saved),JSON.stringify(saved.archive));await new MaterialAiRepository(f.host).validate(saved);assert.deepEqual(f.db.prepare('SELECT first_json,final_json FROM material_ai_units').get(),raw);assert.deepEqual(f.db.prepare('SELECT * FROM material_ai_page_verifications').get(),proof);assert.equal(f.state.calls,3);}finally{await f.dispose();}
});
